// ---- Delayed Hopfield core (pure JS, no DOM) ----
// h_i(t) = sum_mu xi_i^mu a^mu(t) + lambda * sum_mu xi_i^{mu+1} a^mu(t - tau)
// a = C^{-1} m  (pseudo-inverse / projection rule, robust to correlated images)
// Random-sequential Glauber dynamics, time measured in units of the neuron time constant.
function invertMatrix(A) {
  const n = A.length;
  const M = A.map((row, i) => row.concat(Array.from({ length: n }, (_, j) => (i === j ? 1 : 0))));
  for (let col = 0; col < n; col++) {
    let piv = col;
    for (let r = col + 1; r < n; r++) if (Math.abs(M[r][col]) > Math.abs(M[piv][col])) piv = r;
    if (Math.abs(M[piv][col]) < 1e-6) return null;
    [M[col], M[piv]] = [M[piv], M[col]];
    const d = M[col][col];
    for (let j = 0; j < 2 * n; j++) M[col][j] /= d;
    for (let r = 0; r < n; r++) {
      if (r === col) continue;
      const f = M[r][col];
      if (f !== 0) for (let j = 0; j < 2 * n; j++) M[r][j] -= f * M[col][j];
    }
  }
  return M.map(row => row.slice(n));
}

function createNetwork(patterns, opts) {
  const P = patterns.length;
  const N = patterns[0].length;
  const dt = opts.dt || 0.05;
  const xi = new Int8Array(P * N);
  for (let mu = 0; mu < P; mu++) for (let i = 0; i < N; i++) xi[i * P + mu] = patterns[mu][i];

  const C = [];
  for (let mu = 0; mu < P; mu++) {
    C.push([]);
    for (let nu = 0; nu < P; nu++) {
      let s = 0;
      for (let i = 0; i < N; i++) s += xi[i * P + mu] * xi[i * P + nu];
      C[mu].push(s / N);
    }
  }
  let Cinv = invertMatrix(C);
  const hebbFallback = !Cinv;
  if (!Cinv) Cinv = C.map((r, i) => r.map((_, j) => (i === j ? 1 : 0)));

  const H = opts.historyLength;
  const order = new Uint32Array(N);
  for (let i = 0; i < N; i++) order[i] = i;
  let ordPos = N;
  const net = {
    P, N, dt, C, Cinv, hebbFallback,
    s: new Int8Array(N),
    m: new Float64Array(P),
    a: new Float64Array(P),
    ad: new Float64Array(P),
    c: new Float64Array(P),
    hist: new Float64Array(H * P),
    histIdx: 0,
    lambda: opts.lambda ?? 2,
    beta: opts.beta ?? 5,       // Infinity -> T = 0
    delaySteps: opts.delaySteps ?? 200,
    time: 0,
  };

  net.recomputeOverlaps = function () {
    const m = net.m, s = net.s;
    m.fill(0);
    for (let i = 0; i < N; i++) {
      const si = s[i], base = i * P;
      for (let mu = 0; mu < P; mu++) m[mu] += si * xi[base + mu];
    }
    for (let mu = 0; mu < P; mu++) m[mu] /= N;
    net.updateDual();
  };

  net.updateDual = function () {
    for (let mu = 0; mu < P; mu++) {
      let v = 0;
      for (let nu = 0; nu < P; nu++) v += Cinv[mu][nu] * net.m[nu];
      net.a[mu] = v;
    }
  };

  // Start from pattern mu0 with exactly round(p*N) randomly chosen sites flipped.
  net.reset = function (mu0, flipFraction) {
    const s = net.s;
    for (let i = 0; i < N; i++) s[i] = xi[i * P + mu0];
    const k = Math.round(flipFraction * N);
    const idx = new Uint32Array(N);
    for (let i = 0; i < N; i++) idx[i] = i;
    for (let j = 0; j < k; j++) {
      const r = j + Math.floor(Math.random() * (N - j));
      const t = idx[j]; idx[j] = idx[r]; idx[r] = t;
      s[idx[j]] = -s[idx[j]];
    }
    net.hist.fill(0);
    net.histIdx = 0;
    net.time = 0;
    net.recomputeOverlaps();
  };

  net.setSpin = function (i, v) {
    if (net.s[i] === v) return;
    net.s[i] = v;
    const base = i * P, f = (2 * v) / N;
    for (let mu = 0; mu < P; mu++) net.m[mu] += f * xi[base + mu];
  };

  net.step = function () {
    const { m, a, ad, c, hist, s } = net;
    net.updateDual();
    const hp = net.histIdx * P;
    for (let mu = 0; mu < P; mu++) hist[hp + mu] = a[mu];
    const D = Math.min(net.delaySteps, H - 1);
    const dp = ((net.histIdx - D + H) % H) * P;
    for (let mu = 0; mu < P; mu++) ad[mu] = hist[dp + mu];
    for (let mu = 0; mu < P; mu++) c[mu] = a[mu] + net.lambda * ad[(mu - 1 + P) % P];
    net.histIdx = (net.histIdx + 1) % H;

    const n = Math.round(N * dt);
    const beta2 = 2 * net.beta;
    const zeroT = !isFinite(net.beta);
    const invN2 = 2 / N;
    for (let k = 0; k < n; k++) {
      // random-permutation sweeps: every neuron is updated exactly once per unit time
      if (ordPos >= N) {
        for (let j = N - 1; j > 0; j--) { const r = (Math.random() * (j + 1)) | 0; const t = order[j]; order[j] = order[r]; order[r] = t; }
        ordPos = 0;
      }
      const i = order[ordPos++];
      const base = i * P;
      let h = 0;
      for (let mu = 0; mu < P; mu++) h += xi[base + mu] * c[mu];
      let v;
      if (zeroT) v = h > 0 ? 1 : h < 0 ? -1 : s[i];
      else v = Math.random() * (1 + Math.exp(-beta2 * h)) < 1 ? 1 : -1;
      if (v !== s[i]) {
        s[i] = v;
        const f = v * invN2;
        for (let mu = 0; mu < P; mu++) m[mu] += f * xi[base + mu];
      }
    }
    net.time += dt;
  };

  return net;
}

